/**
 * Seed Java Sales Hub from the extracted spreadsheet data.
 *
 * Reference + units come from prisma/seed-data/*.json (generated by
 * scripts/extract_seed.py from the two source .xlsx workbooks).
 *
 * For every SOLD/IN-PROGRESS unit we also synthesize a historical Deal plus
 * PipelineEvents, so that Daily/Monthly/Yearly reports and SPR-YTD derive from
 * a real event ledger rather than typed-in numbers.
 */
import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import bcrypt from "bcryptjs";
import {
  PrismaClient,
  type CaraBayar,
  type Stage,
  type UnitStatus,
  type EventType,
} from "@prisma/client";

const prisma = new PrismaClient();
const DATA = join(process.cwd(), "prisma", "seed-data");

interface RefFile {
  project: { name: string; code: string };
  clusters: { name: string; phases: string[]; types: string[] }[];
  coordinators: string[];
  agencies: string[];
  rotation: { agency: string; coordinator: string; effectiveFrom: string }[];
  teams: string[];
  sales: string[];
  banks: string[];
  promos: string[];
  targets: { scope: string; metric: string; period: string; team?: string; value: number }[];
}
interface UnitRow {
  code: string;
  cluster: string;
  phase: string;
  type: string;
  block: string | null;
  no: string | null;
  status: UnitStatus;
  user: string | null;
  sales: string | null;
  agent: string | null;
  bayar: string | null;
  bank: string | null;
  tglSprCetak: string | null;
  tglUtj: string | null;
  tglAkad: string | null;
}

const ref: RefFile = JSON.parse(readFileSync(join(DATA, "reference.json"), "utf8"));
const units: UnitRow[] = JSON.parse(readFileSync(join(DATA, "units.json"), "utf8"));

interface BatalRow {
  nama: string;
  cluster: string | null;
  kodeUnit: string | null;
  sales: string | null;
  agent: string | null;
  tglUtj: string | null;
  sprCetak: string | null;
  batalTanggal: string | null;
  refund: boolean;
  kategori: string;
  alasan: string;
  alasanRaw: string | null;
}
const batalRows: BatalRow[] = JSON.parse(readFileSync(join(DATA, "batal.json"), "utf8"));

/** ISO string -> Date at UTC midnight of that calendar day (WIB-canonical). */
function toDay(iso: string | null): Date | null {
  if (!iso) return null;
  const [y, m, d] = iso.slice(0, 10).split("-").map(Number);
  if (!y || !m || !d) return null;
  return new Date(Date.UTC(y, m - 1, d));
}

const SOLD: UnitStatus[] = ["REALISASI", "CASH_LUNAS", "PROSES", "HOLD"];

function stageFor(status: UnitStatus): { stage: Stage; events: EventType[] } | null {
  switch (status) {
    case "REALISASI":
      return { stage: "REALISASI", events: ["UTJ", "SPR", "AKAD", "REALISASI"] };
    case "CASH_LUNAS":
      return { stage: "REALISASI", events: ["UTJ", "SPR", "REALISASI"] };
    case "PROSES":
      return { stage: "ACC", events: ["UTJ", "SPR"] };
    case "HOLD":
      return { stage: "UTJ", events: ["UTJ"] };
    default:
      return null;
  }
}

async function main() {
  console.log("Resetting tables…");
  // Order respects FK dependencies.
  await prisma.pipelineEvent.deleteMany();
  await prisma.followUp.deleteMany();
  await prisma.auditLog.deleteMany();
  await prisma.deal.deleteMany();
  await prisma.unit.deleteMany();
  await prisma.rotationAssignment.deleteMany();
  await prisma.target.deleteMany();
  await prisma.unitType.deleteMany();
  await prisma.phase.deleteMany();
  await prisma.cluster.deleteMany();
  await prisma.project.deleteMany();
  await prisma.user.deleteMany();
  await prisma.sales.deleteMany();
  await prisma.team.deleteMany();
  await prisma.coordinator.deleteMany();
  await prisma.agency.deleteMany();
  await prisma.bank.deleteMany();
  await prisma.promo.deleteMany();

  // ---- Project / hierarchy ----
  console.log("Seeding project, clusters, phases, types…");
  const project = await prisma.project.create({
    data: { name: ref.project.name, code: ref.project.code },
  });

  const clusterId = new Map<string, string>();
  const phaseId = new Map<string, string>(); // `${cluster}|${phase}`
  const typeId = new Map<string, string>(); // `${cluster}|${type}`

  for (const c of ref.clusters) {
    const cl = await prisma.cluster.create({
      data: { name: c.name, projectId: project.id },
    });
    clusterId.set(c.name, cl.id);
    for (const p of c.phases) {
      const ph = await prisma.phase.create({ data: { name: p, clusterId: cl.id } });
      phaseId.set(`${c.name}|${p}`, ph.id);
    }
    for (const t of c.types) {
      const ut = await prisma.unitType.create({ data: { name: t, clusterId: cl.id } });
      typeId.set(`${c.name}|${t}`, ut.id);
    }
  }

  // ---- Teams / coordinators / agencies / banks / promos / sales ----
  console.log("Seeding teams, coordinators, agencies, sales, banks, promos…");
  const teamId = new Map<string, string>();
  for (const t of ref.teams) {
    const team = await prisma.team.create({ data: { name: t } });
    teamId.set(t, team.id);
  }

  const coordId = new Map<string, string>();
  for (const name of ref.coordinators) {
    const c = await prisma.coordinator.create({ data: { name } });
    coordId.set(name, c.id);
  }

  const agencyId = new Map<string, string>();
  for (const name of ref.agencies) {
    const a = await prisma.agency.create({ data: { name } });
    agencyId.set(name, a.id);
  }

  const bankId = new Map<string, string>();
  for (const name of ref.banks) {
    const b = await prisma.bank.create({ data: { name } });
    bankId.set(name, b.id);
  }
  for (const name of ref.promos) {
    await prisma.promo.create({ data: { name } });
  }

  const salesId = new Map<string, string>();
  await prisma.sales.createMany({
    data: ref.sales.map((name) => ({ name })),
    skipDuplicates: true,
  });
  for (const s of await prisma.sales.findMany({ select: { id: true, name: true } })) {
    salesId.set(s.name, s.id);
  }

  // ---- Rotation (effective-dated) + fast lookup map for seeding deals ----
  console.log("Seeding rotation assignments…");
  const agencyToCoord = new Map<string, string>();
  for (const r of ref.rotation) {
    const aId = agencyId.get(r.agency);
    const cId = coordId.get(r.coordinator);
    if (!aId || !cId) continue;
    await prisma.rotationAssignment.create({
      data: { agencyId: aId, coordinatorId: cId, effectiveFrom: new Date(r.effectiveFrom) },
    });
    agencyToCoord.set(r.agency, cId);
  }

  // ---- Targets ----
  console.log("Seeding targets…");
  for (const t of ref.targets) {
    await prisma.target.create({
      data: {
        scope: t.scope as never,
        metric: t.metric as never,
        period: t.period,
        value: t.value,
        teamId: t.team ? teamId.get(t.team) ?? null : null,
      },
    });
  }

  // ---- Units + historical Deals + Events ----
  console.log(`Seeding ${units.length} units + historical deals/events…`);
  const unitData: any[] = [];
  const dealData: any[] = [];
  const eventData: any[] = [];
  let skipped = 0;

  for (const u of units) {
    const pId = phaseId.get(`${u.cluster}|${u.phase}`);
    const tId = typeId.get(`${u.cluster}|${u.type}`);
    const cId = clusterId.get(u.cluster);
    if (!pId || !tId || !cId) {
      skipped++;
      continue;
    }
    const uId = randomUUID();
    const sprCetak = toDay(u.tglSprCetak);
    const utjDate = toDay(u.tglUtj);
    const akadDate = toDay(u.tglAkad);

    const mapping = SOLD.includes(u.status) && u.user ? stageFor(u.status) : null;
    let currentDealId: string | null = null;

    if (mapping) {
      const dId = randomUUID();
      currentDealId = dId;
      const sId = u.sales ? salesId.get(u.sales) ?? null : null;
      const aId = u.agent ? agencyId.get(u.agent) ?? null : null;
      const bId = u.bank ? bankId.get(u.bank) ?? null : null;
      const coordinatorId = u.agent ? agencyToCoord.get(u.agent) ?? null : null;
      const anchor = utjDate ?? sprCetak ?? akadDate ?? new Date(Date.UTC(2026, 0, 1));

      // fall back to a placeholder sales/agency if the sheet had none
      const salesFinal = sId ?? [...salesId.values()][0];
      const agencyFinal = aId ?? [...agencyId.values()][0];

      dealData.push({
        id: dId,
        nama: u.user,
        channel: "SITE",
        agencyId: agencyFinal,
        salesId: salesFinal,
        coordinatorId,
        clusterId: cId,
        phaseId: pId,
        unitTypeId: tId,
        statusLead: "COLD",
        stage: mapping.stage,
        tanggalWi: anchor,
        unitId: uId,
        caraBayar: (u.bayar as CaraBayar) ?? null,
        bankId: bId,
        tglUtj: mapping.events.includes("UTJ") ? utjDate ?? anchor : null,
        tglSpr: mapping.events.includes("SPR") ? sprCetak ?? utjDate : null,
        tglAkad: mapping.events.includes("AKAD") ? akadDate ?? sprCetak : null,
        tglRealisasi: mapping.events.includes("REALISASI") ? akadDate ?? sprCetak : null,
      });

      for (const et of mapping.events) {
        let when: Date | null = null;
        if (et === "UTJ") when = utjDate ?? sprCetak;
        else if (et === "SPR") when = sprCetak ?? utjDate;
        else if (et === "AKAD") when = akadDate ?? sprCetak;
        else if (et === "REALISASI") when = akadDate ?? sprCetak;
        if (!when) continue;
        eventData.push({
          dealId: dId,
          unitId: uId,
          type: et,
          eventDate: when,
          toStage: et as Stage,
          actorId: "seed",
        });
      }
    }

    unitData.push({
      id: uId,
      code: u.code,
      phaseId: pId,
      unitTypeId: tId,
      block: u.block,
      no: u.no,
      status: u.status,
      currentDealId,
      tglSprCetak: sprCetak,
      tglUtj: utjDate,
      tglAkad: akadDate,
    });
  }

  // ---- Failed pipeline: real cancellations from BATALREFUND ----
  console.log(`Seeding ${batalRows.length} batal (failed pipeline) records…`);
  const fallbackSales = [...salesId.values()][0];
  const fallbackAgency = [...agencyId.values()][0];
  for (const b of batalRows) {
    const dId = randomUUID();
    const sId = (b.sales && salesId.get(b.sales)) || fallbackSales;
    const aId = (b.agent && agencyId.get(b.agent)) || fallbackAgency;
    const cId = b.cluster ? clusterId.get(b.cluster) ?? null : null;
    const utj = toDay(b.tglUtj);
    const spr = toDay(b.sprCetak);
    const bat = toDay(b.batalTanggal);
    const anchor = utj ?? bat ?? spr ?? new Date(Date.UTC(2026, 0, 1));
    const stage = b.kategori === "SPR" ? "SPR" : "UTJ";
    const coordinatorId = b.agent ? agencyToCoord.get(b.agent) ?? null : null;

    dealData.push({
      id: dId,
      nama: b.nama,
      channel: "SITE",
      agencyId: aId,
      salesId: sId,
      coordinatorId,
      clusterId: cId,
      statusLead: "COLD",
      stage,
      tanggalWi: anchor,
      caraBayar: "KPR",
      tglUtj: utj ?? anchor,
      tglSpr: b.kategori === "SPR" ? spr ?? utj : null,
      batal: true,
      batalKategori: b.kategori as never,
      batalAlasan: b.alasan as never,
      batalTanggal: bat ?? anchor,
      refundStatus: b.refund ? "DONE" : "NONE",
      catatan: b.alasanRaw ?? null,
    });
    // events: the UTJ (counts toward gross), SPR (if applicable), and the BATAL
    if (utj) eventData.push({ dealId: dId, type: "UTJ", eventDate: utj, toStage: "UTJ", actorId: "seed" });
    if (b.kategori === "SPR" && spr)
      eventData.push({ dealId: dId, type: "SPR", eventDate: spr, toStage: "SPR", actorId: "seed" });
    if (bat)
      eventData.push({
        dealId: dId,
        type: "BATAL",
        eventDate: bat,
        fromStage: stage as never,
        actorId: "seed",
        meta: { kategori: b.kategori, alasan: b.alasan },
      });
  }

  // chunked inserts
  const chunk = <T,>(arr: T[], n: number) =>
    Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

  for (const c of chunk(unitData, 500)) await prisma.unit.createMany({ data: c, skipDuplicates: true });
  for (const c of chunk(dealData, 500)) await prisma.deal.createMany({ data: c });
  for (const c of chunk(eventData, 1000)) await prisma.pipelineEvent.createMany({ data: c });

  // ---- Demo users ----
  console.log("Seeding demo users…");
  const pw = await bcrypt.hash("password", 10);
  const anySales = await prisma.sales.findFirst();
  await prisma.user.createMany({
    data: [
      { name: "Manajemen", email: "admin@javasaleshub.test", passwordHash: pw, role: "MANAGEMENT" },
      { name: "Sales Demo", email: "sales@javasaleshub.test", passwordHash: pw, role: "SALES", salesId: anySales?.id ?? null },
      { name: "Collection Demo", email: "collection@javasaleshub.test", passwordHash: pw, role: "COLLECTION" },
    ],
  });

  console.log("\n✔ Seed complete.");
  console.log(`  units: ${unitData.length} (skipped ${skipped})`);
  console.log(`  historical deals: ${dealData.length}`);
  console.log(`  pipeline events: ${eventData.length}`);
  console.log(`  agencies: ${agencyId.size}  sales: ${salesId.size}  coordinators: ${coordId.size}`);
  console.log("\n  Login: admin@ / sales@ / collection@ javasaleshub.test — password: 'password'");
}

main()
  .then(() => prisma.$disconnect())
  .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
  });
